const refunds = $('Fetch Refund Data').all().map(i=>i.json);
const orders = $('Fetch Order Data').all().map(i=>i.json);

const totalOrders = orders.length;
const totalRefunds = refunds.length;
const refundRate = totalOrders > 0 ? ((totalRefunds/totalOrders)*100).toFixed(1) : 0;

const byProduct = {};
refunds.forEach(r => {
  const prod = r['Product Name'] || 'Unknown';
  if (!byProduct[prod]) byProduct[prod] = { count: 0, reasons: [] };
  byProduct[prod].count++;
  if (r['Refund Reason']) byProduct[prod].reasons.push(r['Refund Reason']);
});

const byReason = {};
refunds.forEach(r => {
  const reason = r['Refund Reason'] || 'Not specified';
  byReason[reason] = (byReason[reason]||0) + 1;
});

const topProducts = Object.entries(byProduct).sort((a,b)=>b[1].count-a[1].count).slice(0,5);
const topReasons = Object.entries(byReason).sort((a,b)=>b[1]-a[1]).slice(0,5);

const serialRefunders = {};
refunds.forEach(r => {
  const email = r['Customer Email'];
  if (email) serialRefunders[email] = (serialRefunders[email]||0) + 1;
});
const suspiciousCustomers = Object.entries(serialRefunders).filter(([,count])=>count>=3).map(([email,count])=>({email,refund_count:count}));

return [{ json: { refund_rate: refundRate, total_refunds: totalRefunds, total_orders: totalOrders, top_products: topProducts.map(([name,d])=>({name,count:d.count,top_reason:d.reasons[0]||''})), top_reasons: topReasons.map(([reason,count])=>({reason,count})), suspicious_customers: suspiciousCustomers } }];

const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const analysis = JSON.parse(raw);
return [{ json: { ...analysis, stats: $('Process Refund Stats').item.json } }];

